def leaf_count(exc):
    if isinstance(exc, BaseExceptionGroup):
        return sum(leaf_count(e) for e in exc.exceptions)
    return 1

def retry_split(group):
    retryable, other = group.split(lambda e: isinstance(e, TimeoutError))
    return (leaf_count(retryable) if retryable else 0, leaf_count(other) if other else 0)

demo = ExceptionGroup("net", [
    TimeoutError("a"),
    ConnectionError("b"),
    ExceptionGroup("inner", [TimeoutError("c"), ValueError("d")]),
])
print(retry_split(demo))

def parse_cell(cell, line):
    try:
        return int(cell)
    except ValueError as exc:
        exc.add_note(f"line {line}: {cell!r}")
        raise

try:
    parse_cell("abc", 3)
except ValueError as exc:
    print(exc.__notes__)
